import numpy as np


def confusion_matrix(y_true, y_pred, num_classes):
    cm = np.zeros((num_classes, num_classes), dtype=int)
    for t, p in zip(y_true, y_pred):
        cm[t][p] += 1
    return cm


def per_class_accuracy(cm):
    rows = cm.sum(axis=1)
    return np.where(rows > 0, np.diag(cm) / np.maximum(rows, 1), 0.0)


def checkpoint_epochs(val_accuracies):
    saved, best = [], float("-inf")
    for epoch, acc in enumerate(val_accuracies):
        if acc > best:
            best = acc
            saved.append(epoch)
    return saved


classes = ["plane", "car", "bird"]
y_true = [0, 0, 1, 1, 1, 2, 2, 2, 2]
y_pred = [0, 1, 1, 1, 0, 2, 2, 1, 2]
cm = confusion_matrix(y_true, y_pred, 3)
print("confusion matrix (rows = true, columns = predicted):")
print(cm)
acc = per_class_accuracy(cm) if cm is not None else None
if acc is not None:
    for name, a in zip(classes, acc):
        print(f"{name}: {a:.2f}")
print("checkpoints saved at epochs:", checkpoint_epochs([0.41, 0.55, 0.53, 0.61, 0.60]))
